function textOf(j) {
  if (!j) return '';
  if (typeof j.mergedResponse === 'string' && j.mergedResponse) return j.mergedResponse;
  const parts = (j.content && j.content.parts) || (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts);
  if (Array.isArray(parts)) return parts.map(p => p.text || '').join('');
  if (typeof j.text === 'string') return j.text;
  return JSON.stringify(j);
}
function parseJson(t) {
  const s = String(t || '').trim().replace(/^\s*\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60\s*$/, '');
  const a = s.indexOf('{'); const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return { parse_error: true, raw: String(t || '') };
}
const brief = $('Normalize Brief').first().json;
const content = parseJson(textOf($input.first().json));
const wantsVisuals = /Visuals/i.test(brief.content_types);
return [{ json: { ...brief, content, wantsVisuals } }];

const d = $input.first().json;
let prompts = Array.isArray(d.content && d.content.visual_prompts) ? d.content.visual_prompts.filter(p => p && p.prompt) : [];
if (!prompts.length) prompts = [{ use: 'Hero visual', aspect_ratio: '1:1', prompt: 'Premium marketing photo for ' + d.brand + ': ' + d.product + '. Audience: ' + d.audience + '. Clean composition, natural light, no text.' }];
return prompts.slice(0, 3).map(p => ({ json: { use: p.use || 'Visual', aspect_ratio: p.aspect_ratio || '1:1', prompt: p.prompt } }));

const d = $('Parse Content').first().json;
const c = d.content || {};
const ar = /Arabic/i.test(d.language);
let prompts = [];
try { prompts = $('Split Visual Prompts').all().map(i => i.json); } catch (e) {}
const images = [];
if (d.wantsVisuals) {
  const items = $input.all();
  for (let i = 0; i < items.length; i++) {
    const b = items[i].binary && items[i].binary.data;
    if (!b) continue;
    try {
      const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
      images.push({ mime: b.mimeType || 'image/png', b64: buf.toString('base64'), use: (prompts[i] && prompts[i].use) || 'Visual', prompt: (prompts[i] && prompts[i].prompt) || '' });
    } catch (e) {}
  }
}
const L = ar ? { title: 'باقة المحتوى', idea: 'الفكرة الرئيسية', msgs: 'الرسائل الأساسية', blog: 'مقال المدونة', social: 'بوستات السوشيال ميديا', ads: 'نصوص الإعلانات', lp: 'نص صفحة الهبوط', visuals: 'الصور', copy: 'نسخ', script: 'سكريبت الفيديو', visual: 'وصف الصورة', time: 'أفضل وقت', faq: 'أسئلة شائعة' } : { title: 'Content Pack', idea: 'Big idea', msgs: 'Key messages', blog: 'Blog article', social: 'Social media posts', ads: 'Ad copy', lp: 'Landing page copy', visuals: 'Visuals', copy: 'Copy', script: 'Video script', visual: 'Visual brief', time: 'Best time', faq: 'FAQ' };
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function arr(v) { return Array.isArray(v) ? v : (v ? [v] : []); }
function inline(s) { return esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>'); }
function md(t) {
  const lines = String(t || '').split(/\r?\n/); let out = ''; let inList = false;
  for (const raw of lines) {
    const l = raw.trim();
    if (/^[-*] /.test(l)) { if (!inList) { out += '<ul>'; inList = true; } out += '<li>' + inline(l.slice(2)) + '</li>'; continue; }
    if (inList) { out += '</ul>'; inList = false; }
    if (!l) continue;
    const h = l.match(/^(#{1,4})\s+(.*)$/);
    if (h) { const n = Math.min(4, h[1].length + 1); out += '<h' + n + '>' + inline(h[2]) + '</h' + n + '>'; } else out += '<p>' + inline(l) + '</p>';
  }
  if (inList) out += '</ul>';
  return out;
}
let n = 0;
function copyBox(text) { n++; return '<div class="cp"><button onclick="cp(\'t' + n + '\')">' + L.copy + '</button><div id="t' + n + '" class="txt">' + esc(text).replace(/\n/g, '<br>') + '</div></div>'; }
let h = '';
h += '<section><h2>' + L.idea + '</h2><p class="big">' + esc(c.big_idea) + '</p>' + (arr(c.key_messages).length ? '<h3>' + L.msgs + '</h3><ul>' + arr(c.key_messages).map(m => '<li>' + esc(m) + '</li>').join('') + '</ul>' : '') + (c.parse_error ? '<pre>' + esc(c.raw) + '</pre>' : '') + '</section>';
const posts = arr(c.social_posts);
if (posts.length) {
  h += '<section><h2>' + L.social + ' (' + posts.length + ')</h2><div class="cards">' + posts.map(p => {
    const full = [p.hook, p.caption, p.cta, arr(p.hashtags).map(x => String(x).startsWith('#') ? x : '#' + x).join(' ')].filter(Boolean).join('\n\n');
    return '<div class="card"><div class="tags"><span class="tag p-' + esc(String(p.platform).toLowerCase()) + '">' + esc(p.platform) + '</span><span class="tag">' + esc(p.format) + '</span>' + (p.best_time ? '<span class="tag">' + L.time + ': ' + esc(p.best_time) + '</span>' : '') + '</div>' + copyBox(full) + (p.video_script ? '<details><summary>' + L.script + '</summary>' + copyBox(p.video_script) + '</details>' : '') + (p.visual_brief ? '<p class="muted"><b>' + L.visual + ':</b> ' + esc(p.visual_brief) + '</p>' : '') + '</div>';
  }).join('') + '</div></section>';
}
const ads = arr(c.ad_copy);
if (ads.length) {
  h += '<section><h2>' + L.ads + '</h2><div class="cards">' + ads.map(a => '<div class="card"><div class="tags"><span class="tag">' + esc(a.platform) + '</span><span class="tag">' + esc(a.variant) + '</span></div><b>Headlines</b>' + copyBox(arr(a.headlines).join('\n')) + (a.primary_text ? '<b>Primary text</b>' + copyBox(a.primary_text) : '') + (arr(a.descriptions).length ? '<b>Descriptions</b>' + copyBox(arr(a.descriptions).join('\n')) : '') + '<p class="muted">CTA: ' + esc(a.cta) + '</p></div>').join('') + '</div></section>';
}
const b = c.blog;
if (b && (b.title || b.body_markdown)) {
  h += '<section><h2>' + L.blog + '</h2><div class="meta"><div><b>Meta title:</b> ' + esc(b.meta_title) + '</div><div><b>Meta description:</b> ' + esc(b.meta_description) + '</div><div><b>Slug:</b> /' + esc(b.slug) + '</div><div><b>Focus keyword:</b> ' + esc(b.focus_keyword) + ' · ' + esc(arr(b.secondary_keywords).join(', ')) + '</div></div><article><h1>' + esc(b.title) + '</h1>' + md(b.body_markdown) + (b.cta ? '<p class="cta">' + esc(b.cta) + '</p>' : '') + '</article><details><summary>Markdown</summary>' + copyBox(b.body_markdown) + '</details></section>';
}
const lp = c.landing_page;
if (lp && lp.hero_headline) {
  h += '<section><h2>' + L.lp + '</h2><div class="meta"><div><b>Meta title:</b> ' + esc(lp.meta_title) + '</div><div><b>Meta description:</b> ' + esc(lp.meta_description) + '</div></div><div class="hero"><h1>' + esc(lp.hero_headline) + '</h1><p>' + esc(lp.hero_subheadline) + '</p><span class="btn">' + esc(lp.primary_cta) + '</span></div>' + arr(lp.sections).map(s => '<h3>' + esc(s.title) + '</h3><p>' + esc(s.body) + '</p>').join('') + (lp.social_proof ? '<blockquote>' + esc(lp.social_proof) + '</blockquote>' : '') + (arr(lp.faq).length ? '<h3>' + L.faq + '</h3>' + arr(lp.faq).map(f => '<details><summary>' + esc(f.q) + '</summary><p>' + esc(f.a) + '</p></details>').join('') : '') + '</section>';
}
if (images.length) {
  h += '<section><h2>' + L.visuals + '</h2><div class="cards">' + images.map(im => '<figure class="card"><img src="data:' + im.mime + ';base64,' + im.b64 + '" alt="' + esc(im.use) + '"><figcaption><b>' + esc(im.use) + '</b><br><small class="muted">' + esc(im.prompt) + '</small></figcaption></figure>').join('') + '</div></section>';
} else if (arr(c.visual_prompts).length) {
  h += '<section><h2>' + L.visuals + '</h2>' + arr(c.visual_prompts).map(v => '<p><b>' + esc(v.use) + ' (' + esc(v.aspect_ratio) + ')</b></p>' + copyBox(v.prompt)).join('') + '</section>';
}
const css = ':root{--bg:#f6f7fb;--card:#fff;--ink:#1d2433;--muted:#667085;--line:#e4e7ec;--acc:#3b5bdb}@media (prefers-color-scheme:dark){:root{--bg:#0f131a;--card:#171c26;--ink:#e6e9ef;--muted:#98a2b3;--line:#2a3140;--acc:#7c9cff}}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.7 system-ui,-apple-system,Segoe UI,Tahoma,sans-serif}.wrap{max-width:1100px;margin:0 auto;padding:24px 16px}header{border-bottom:3px solid var(--acc);margin-bottom:16px;padding-bottom:10px}header h1{margin:0}section{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px;margin:16px 0}h2{color:var(--acc);margin:0 0 12px}.big{font-size:19px;font-weight:600}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px}.card{border:1px solid var(--line);border-radius:10px;padding:14px;margin:0}.tags{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}.tag{border:1px solid var(--line);border-radius:99px;padding:1px 10px;font-size:12px}.p-facebook{background:#1877f2;color:#fff}.p-instagram{background:#c13584;color:#fff}.p-tiktok{background:#111;color:#fff}.p-snapchat{background:#fffc00;color:#111}.cp{background:var(--bg);border-radius:8px;padding:10px;margin:6px 0}.cp button{float:inline-end;border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:6px;cursor:pointer;font-size:12px}.muted{color:var(--muted)}.meta{background:var(--bg);border-radius:8px;padding:10px;font-size:14px;margin-bottom:12px}article h1{font-size:24px}.hero{background:var(--bg);border-radius:10px;padding:20px;text-align:center}.btn{display:inline-block;background:var(--acc);color:#fff;border-radius:8px;padding:8px 18px}img{width:100%;border-radius:8px}blockquote{border-inline-start:3px solid var(--acc);margin:10px 0;padding:4px 12px;color:var(--muted)}details{margin:6px 0}summary{cursor:pointer;color:var(--acc)}pre{white-space:pre-wrap}';
const js = 'function cp(id){var t=document.getElementById(id).innerText;navigator.clipboard.writeText(t);}';
const html = '<!DOCTYPE html><html lang="' + (ar ? 'ar' : 'en') + '" dir="' + (ar ? 'rtl' : 'ltr') + '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(L.title + ' - ' + d.brand) + '</title><style>' + css + '</style></head><body><div class="wrap"><header><h1>' + esc(L.title) + ': ' + esc(d.brand) + '</h1><div class="muted">' + esc(d.goal) + ' · ' + esc(d.platforms) + ' · ' + $now.toFormat('yyyy-MM-dd HH:mm') + '</div></header>' + h + '</div><script>' + js + '</script></body></html>';
const fileName = 'content-pack-' + (String(d.brand || 'brand').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'brand') + '-' + $now.toFormat('yyyyMMdd-HHmm') + '.html';
const binary = { data: await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), fileName, 'text/html') };
return [{ json: { mode: d.mode, brand: d.brand, goal: d.goal, platforms: d.platforms, language: d.language, big_idea: c.big_idea || '', content: c, images_generated: images.length, file_name: fileName }, binary }];
